values ('National Agency of Public Registry', 'https://napr.gov.ge/en/page/fees-and-terms', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Registration of an individual entrepreneur: 1 working day, 26 GEL; on the day of filing the application, 75 GEL. Registration of an entrepreneur (except for an individual entrepreneur): 1 working day, 200 GEL; on the day of filing the application, 400 GEL. (The page separates term and fee with a dash.)')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Invest in Georgia', 'https://www.investingeorgia.org/resources/how-to-register-a-business/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"The registration is carried out by the National Agency of Public Registry." "all services needed for the business registration are provided by the Public Registry through the Public Service Hall." Founders'' charter signed, notarised and apostilled or legalised; proof of a legal address, a lease or landlord letter notarised by a Georgian notary unless signed before a Public Registry representative.')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('PwC Worldwide Tax Summaries', 'https://taxsummaries.pwc.com/georgia/individual/taxes-on-personal-income', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Individual entrepreneurs under the GEL 500,000 turnover limit "may register as a small business", taxed at 1% of turnover; "The rate increases to 3% if annual turnover will exceed GEL 500,000." "Individuals with annual turnover of less than 30,000 Georgian lari (GEL), no employees, and who register as a micro business will be exempt from tax on their business income."')
on conflict do nothing;
