insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('112 Georgia (LEPL of the Ministry of Internal Affairs)', 'https://112.gov.ge/?p=1715', true, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', '"Any situation that requires the assistance of Police, Ambulance and/or Fire/Rescue teams, is considered as emergency." Works "24/7 throughout the whole country", "since 2012". Reachable from "Cell phones without SIM cards", "From fixed phone with negative balance" and "From cell phone with negative balance".')
on conflict do nothing;
insert into public.expat_citations
  (publisher, url, official, published_on, effective_from, observed_at, language, excerpt)
values ('Madloba.info', 'https://madloba.info/en/faq/healthcare-and-insurance/', false, null, null,
        '2026-10-24T00:00:00Z'::timestamptz, 'en', 'Ambulance, police and fire "on the single number 112, free from any phone, even without a SIM card". Medical tests are done at private laboratories and multi-specialty clinics, and "most don''t require a doctor''s referral". Checked Oct. 3, 2026.')
on conflict do nothing;

-- Keep one row per (publisher, url): re-running must not accumulate copies.
delete from public.expat_citations a
using public.expat_citations b
where a.publisher = b.publisher
  and a.url is not distinct from b.url
  and a.ctid > b.ctid
  and not exists (select 1 from public.expat_fact_citations fc where fc.citation_id = a.id)
  and not exists (select 1 from public.expat_cost_observations co where co.citation_id = a.id)
  and not exists (select 1 from public.expat_places p where p.citation_id = a.id);

-- health-and-safety
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('health-and-safety', 'GE', 'HEALTHCARE', 'LIVE', '{"en":{"title":"Health and safety","summary":"One number covers every emergency in Georgia: 112. For everything else there are pharmacies on almost every corner and private clinics in the cities.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"In an emergency call 112 for police, an ambulance or the fire service. It works all over Georgia, day and night, and you can call it even from a phone with no SIM card or no credit. Save it in your phone now."},{"kind":"PRACTICAL","heading":"Pharmacies","body":"Cities have many pharmacies, including large chains, and some stay open through the night. The pharmacist can help with everyday things. Some medicines need a doctor''s prescription, so if you take something regularly, bring your prescription and know the generic name of the medicine, not only the brand."},{"kind":"WHERE","heading":"Doctors, clinics and tests","body":"Most foreigners use private clinics, which are easy to find in Tbilisi and Batumi. Blood tests and other checks are done at private laboratories and multi specialty clinics, and most do not need a referral from a doctor. When you book, ask whether the doctor speaks a language you are comfortable in."},{"kind":"NOTES","heading":"Insurance","body":"Private care is paid for, so health insurance that works in Georgia is worth having from the first day. Before you buy, check which clinics it works with and whether you pay first and claim back later. Whether a foreign resident can join the state health programme is something we have not been able to confirm. Ask the Ministry of Health (moh.gov.ge) about your own status before you count on it."},{"kind":"PRACTICAL","heading":"Staying safe day to day","body":"Take care crossing roads, because drivers can be fast, and use crossings and underpasses where you can. In the mountains the weather changes quickly, so tell someone your route and check the forecast before a hike. If you are unsure about anything, 112 is the number to call."}]},"ka":{"title":"ჯანმრთელობა და უსაფრთხოება","summary":"საქართველოში ყველა გადაუდებელ შემთხვევაზე ერთი ნომერია: 112. დანარჩენისთვის აფთიაქი თითქმის ყველა კუთხეშია, ქალაქებში კი კერძო კლინიკებია.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"გადაუდებელ შემთხვევაში დარეკეთ 112-ზე პოლიციის, სასწრაფოს ან სახანძრო სამსახურის გამოსაძახებლად. ის მთელ საქართველოში მუშაობს, დღე და ღამე, და დარეკვა შეგიძლიათ სიმ ბარათის ან ბალანსის გარეშეც. შეინახეთ ტელეფონში ახლავე."},{"kind":"PRACTICAL","heading":"აფთიაქები","body":"ქალაქებში ბევრი აფთიაქია, მათ შორის დიდი ქსელები, და ზოგი მთელი ღამე მუშაობს. ფარმაცევტი ყოველდღიურ საკითხებში დაგეხმარებათ. ზოგი წამალი ექიმის რეცეპტით გაიცემა, ამიტომ, თუ რამეს რეგულარულად იღებთ, თან იქონიეთ რეცეპტი და იცოდეთ წამლის ზოგადი სახელი და არა მხოლოდ ბრენდი."},{"kind":"WHERE","heading":"ექიმები, კლინიკები და ანალიზები","body":"უცხოელების უმეტესობა კერძო კლინიკებით სარგებლობს, რომლებიც თბილისსა და ბათუმში ადვილად მოიძებნება. სისხლის ანალიზი და სხვა კვლევები კერძო ლაბორატორიებსა და მრავალპროფილიან კლინიკებში კეთდება და უმეტესობას ექიმის მიმართვა არ სჭირდება. ჩაწერისას ჰკითხეთ, ლაპარაკობს თუ არა ექიმი თქვენთვის მოსახერხებელ ენაზე."},{"kind":"NOTES","heading":"დაზღვევა","body":"კერძო მომსახურება ფასიანია, ამიტომ საქართველოში მოქმედი ჯანმრთელობის დაზღვევა პირველივე დღიდან ღირს. ყიდვამდე გადაამოწმეთ, რომელ კლინიკებთან მუშაობს და ჯერ თქვენ იხდით და მერე ანაზღაურებას იღებთ თუ არა. შეუძლია თუ არა უცხოელ რეზიდენტს სახელმწიფო ჯანდაცვის პროგრამაში ჩართვა, ჯერ ვერ დავადასტურეთ. სანამ ამის იმედი გექნებათ, თქვენი სტატუსის შესახებ ჰკითხეთ ჯანდაცვის სამინისტროს (moh.gov.ge)."},{"kind":"PRACTICAL","heading":"ყოველდღიური უსაფრთხოება","body":"ფრთხილად გადადით გზაზე, რადგან მძღოლები შეიძლება სწრაფად მოძრაობდნენ, და სადაც შეგიძლიათ, გამოიყენეთ გადასასვლელი და მიწისქვეშა გადასასვლელი. მთაში ამინდი სწრაფად იცვლება, ამიტომ ლაშქრობამდე ვინმეს უთხარით თქვენი მარშრუტი და ნახეთ პროგნოზი. თუ რამეში დარწმუნებული არ ხართ, დარეკეთ 112-ზე."}]},"ru":{"title":"Здоровье и безопасность","summary":"В Грузии на любой экстренный случай один номер: 112. Для всего остального аптеки есть почти на каждом углу, а в городах работают частные клиники.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"В экстренной ситуации звоните 112, чтобы вызвать полицию, скорую или пожарных. Номер работает по всей Грузии днём и ночью, и позвонить можно даже с телефона без SIM карты или без денег на счёте. Сохраните его в телефоне прямо сейчас."},{"kind":"PRACTICAL","heading":"Аптеки","body":"В городах много аптек, в том числе крупные сети, и некоторые работают круглосуточно. Фармацевт поможет с повседневными вещами. Некоторые лекарства отпускают только по рецепту врача, поэтому, если вы что-то принимаете постоянно, возьмите рецепт и знайте международное название лекарства, а не только бренд."},{"kind":"WHERE","heading":"Врачи, клиники и анализы","body":"Большинство иностранцев ходит в частные клиники, в Тбилиси и Батуми их легко найти. Анализы крови и другие обследования делают в частных лабораториях и многопрофильных клиниках, и для большинства не нужно направление врача. При записи спросите, говорит ли врач на удобном вам языке."},{"kind":"NOTES","heading":"Страховка","body":"Частная медицина платная, поэтому медицинская страховка, которая работает в Грузии, нужна с первого дня. Перед покупкой проверьте, с какими клиниками она работает и платите ли вы сначала сами, а потом получаете возмещение. Может ли иностранный резидент участвовать в государственной программе здравоохранения, мы подтвердить не смогли. Прежде чем на это рассчитывать, спросите о своём статусе в Министерстве здравоохранения (moh.gov.ge)."},{"kind":"PRACTICAL","heading":"Безопасность каждый день","body":"Осторожно переходите дорогу, водители бывают быстрыми, и по возможности пользуйтесь переходами и подземными переходами. В горах погода меняется быстро, так что перед походом скажите кому-нибудь свой маршрут и посмотрите прогноз. Если в чём-то не уверены, звоните 112."}]},"tr":{"title":"Sağlık ve güvenlik","summary":"Gürcistan''da her acil durum için tek numara var: 112. Geri kalan her şey için neredeyse her köşede eczane, şehirlerde de özel klinikler var.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Acil durumda polis, ambulans ya da itfaiye için 112''yi arayın. Tüm Gürcistan''da gece gündüz çalışır ve SIM kartı ya da bakiyesi olmayan bir telefondan bile arayabilirsiniz. Şimdi telefonunuza kaydedin."},{"kind":"PRACTICAL","heading":"Eczaneler","body":"Şehirlerde büyük zincirler dahil çok sayıda eczane var, bazıları gece boyunca açık. Eczacı günlük konularda yardımcı olur. Bazı ilaçlar yalnızca reçeteyle verilir, düzenli bir ilaç kullanıyorsanız reçetenizi getirin ve ilacın sadece marka adını değil etken madde adını da bilin."},{"kind":"WHERE","heading":"Doktorlar, klinikler ve tahliller","body":"Yabancıların çoğu, Tiflis ve Batum''da kolayca bulunan özel klinikleri kullanır. Kan tahlilleri ve diğer kontroller özel laboratuvarlarda ve çok branşlı kliniklerde yapılır, çoğu için doktor sevki gerekmez. Randevu alırken doktorun rahat ettiğiniz bir dili konuşup konuşmadığını sorun."},{"kind":"NOTES","heading":"Sigorta","body":"Özel sağlık hizmeti ücretlidir, bu yüzden Gürcistan''da geçerli bir sağlık sigortası ilk günden işe yarar. Almadan önce hangi kliniklerle çalıştığını ve önce sizin ödeyip sonra geri mi aldığınızı kontrol edin. Yabancı bir mukimin devlet sağlık programına katılıp katılamayacağını doğrulayamadık. Buna güvenmeden önce kendi durumunuzu Sağlık Bakanlığı''na (moh.gov.ge) sorun."},{"kind":"PRACTICAL","heading":"Günlük güvenlik","body":"Yolu dikkatli geçin, sürücüler hızlı olabilir, mümkün olduğunda yaya geçidi ve alt geçit kullanın. Dağlarda hava hızlı değişir, yürüyüşten önce birine rotanızı söyleyin ve hava tahminine bakın. Emin olmadığınız bir şey olursa 112''yi arayın."}]},"ar":{"title":"الصحة والسلامة","summary":"رقم واحد لكل حالات الطوارئ في جورجيا: 112. ولكل ما عدا ذلك هناك صيدليات في كل زاوية تقريبًا، وعيادات خاصة في المدن.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"في الطوارئ اتصل بـ 112 لطلب الشرطة أو الإسعاف أو الدفاع المدني. يعمل في كل جورجيا ليلًا ونهارًا، ويمكنك الاتصال به حتى من هاتف بلا شريحة أو بلا رصيد. احفظه في هاتفك الآن."},{"kind":"PRACTICAL","heading":"الصيدليات","body":"في المدن صيدليات كثيرة، منها سلاسل كبيرة، وبعضها يفتح طوال الليل. والصيدلي يساعدك في الأمور اليومية. بعض الأدوية لا تُصرف إلا بوصفة طبيب، فإن كنت تتناول دواء بانتظام فخذ وصفتك معك واعرف الاسم العلمي للدواء لا الاسم التجاري فقط."},{"kind":"WHERE","heading":"الأطباء والعيادات والتحاليل","body":"معظم الأجانب يراجعون عيادات خاصة، وهي سهلة الإيجاد في تبليسي وباتومي. تحاليل الدم والفحوص الأخرى تُجرى في مختبرات خاصة وعيادات متعددة التخصصات، ومعظمها لا يحتاج إلى تحويل من طبيب. عند الحجز اسأل هل يتكلم الطبيب لغة ترتاح لها."},{"kind":"NOTES","heading":"التأمين","body":"الرعاية الخاصة مدفوعة، لذلك يستحق التأمين الصحي الذي يعمل في جورجيا أن يكون معك من أول يوم. قبل الشراء تأكد من العيادات التي يتعامل معها، وهل تدفع أنت أولًا ثم تسترد المبلغ. أما هل يستطيع المقيم الأجنبي الانضمام إلى البرنامج الصحي الحكومي فلم نتمكن من التأكد منه، فاسأل وزارة الصحة (moh.gov.ge) عن وضعك قبل أن تعتمد عليه."},{"kind":"PRACTICAL","heading":"السلامة في الحياة اليومية","body":"انتبه عند عبور الطريق لأن السائقين قد يسرعون، واستخدم ممرات المشاة والأنفاق متى استطعت. في الجبال يتغير الطقس بسرعة، فأخبر أحدًا بمسارك وتابع النشرة الجوية قبل أي رحلة مشي. وإذا لم تكن متأكدًا من شيء، اتصل بـ 112."}]},"he":{"title":"בריאות ובטיחות","summary":"בגאורגיה יש מספר אחד לכל מקרה חירום: 112. לכל השאר יש בתי מרקחת כמעט בכל פינה ומרפאות פרטיות בערים.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"במקרה חירום התקשרו ל־112 כדי להזמין משטרה, אמבולנס או כבאות. המספר עובד בכל גאורגיה, ביום ובלילה, ואפשר להתקשר אליו אפילו מטלפון בלי סים או בלי יתרה. שמרו אותו בטלפון עכשיו."},{"kind":"PRACTICAL","heading":"בתי מרקחת","body":"בערים יש הרבה בתי מרקחת, כולל רשתות גדולות, וחלקם פתוחים כל הלילה. הרוקח יכול לעזור בדברים יומיומיים. חלק מהתרופות ניתנות רק במרשם רופא, אז אם אתם לוקחים משהו באופן קבוע, הביאו את המרשם ודעו את השם הגנרי של התרופה, לא רק את המותג."},{"kind":"WHERE","heading":"רופאים, מרפאות ובדיקות","body":"רוב הזרים משתמשים במרפאות פרטיות, וקל למצוא אותן בטביליסי ובבטומי. בדיקות דם ובדיקות אחרות נעשות במעבדות פרטיות ובמרפאות רב תחומיות, ולרובן לא צריך הפניה מרופא. כשקובעים תור, שאלו אם הרופא מדבר בשפה שנוחה לכם."},{"kind":"NOTES","heading":"ביטוח","body":"רפואה פרטית עולה כסף, אז ביטוח בריאות שעובד בגאורגיה שווה מהיום הראשון. לפני שקונים, בדקו עם אילו מרפאות הוא עובד והאם משלמים קודם ומקבלים החזר אחר כך. אם תושב זר יכול להצטרף לתוכנית הבריאות הממלכתית, את זה לא הצלחנו לאמת. שאלו את משרד הבריאות (moh.gov.ge) על המעמד שלכם לפני שסומכים על זה."},{"kind":"PRACTICAL","heading":"בטיחות ביומיום","body":"היזהרו כשחוצים כביש, כי נהגים יכולים לנסוע מהר, והשתמשו במעברי חצייה ובמעברים תת קרקעיים כשאפשר. בהרים מזג האוויר משתנה מהר, אז ספרו למישהו על המסלול ובדקו תחזית לפני טיול. אם אתם לא בטוחים במשהו, 112 הוא המספר."}]}}'::jsonb,
        'PROCESS', 'OFFICIAL_REQUIREMENT', 90,
        true, false, null,
        now(), now() + interval '90 days')
on conflict (slug) do update set
  domain = excluded.domain,
  pathway = excluded.pathway,
  content = excluded.content,
  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'emergency-number-112', 'PROCESS', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"112 is the single emergency number in Georgia for police, ambulance and fire and rescue. It works 24 hours a day across the whole country, including from mobile phones without a SIM card or with a negative balance.","ka":"112 საქართველოში ერთიანი საგანგებო ნომერია პოლიციის, სასწრაფოს და სახანძრო სამაშველო სამსახურისთვის. ის მთელ ქვეყანაში 24 საათი მუშაობს, მათ შორის სიმ ბარათის გარეშე ან უარყოფითი ბალანსით მობილურიდანაც.","ru":"112 это единый номер экстренных служб в Грузии: полиция, скорая и пожарно спасательная служба. Он работает круглосуточно по всей стране, в том числе с мобильного без SIM карты или с отрицательным балансом.","tr":"112, Gürcistan''da polis, ambulans ve itfaiye ve kurtarma için tek acil durum numarasıdır. Tüm ülkede 24 saat çalışır, SIM kartı olmayan ya da bakiyesi eksi olan cep telefonlarından da aranabilir.","ar":"الرقم 112 هو رقم الطوارئ الموحد في جورجيا للشرطة والإسعاف والإطفاء والإنقاذ. يعمل على مدار الساعة في كل البلاد، حتى من هاتف محمول بلا شريحة أو برصيد سالب.","he":"112 הוא מספר החירום האחיד בגאורגיה למשטרה, לאמבולנס ולכבאות והצלה. הוא פועל 24 שעות ביממה בכל הארץ, גם מטלפון נייד בלי סים או עם יתרה שלילית."}'::jsonb, '{"number":"112"}'::jsonb, null,
       false
from public.expat_topics where slug = 'health-and-safety'
on conflict (topic_id, fact_key) do update set
  fact_class = excluded.fact_class,
  register = excluded.register,
  availability = excluded.availability,
  statement = excluded.statement,
  value = excluded.value,
  applies_to_nationalities = excluded.applies_to_nationalities,
  needs_review = excluded.needs_review,
  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'health-and-safety'
cross join lateral (
  select id from public.expat_citations
  where publisher = '112 Georgia (LEPL of the Ministry of Internal Affairs)' and url is not distinct from 'https://112.gov.ge/?p=1715'
  order by created_at limit 1) c
where f.fact_key = 'emergency-number-112'
on conflict do nothing;
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'health-and-safety'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Madloba.info' and url is not distinct from 'https://madloba.info/en/faq/healthcare-and-insurance/'
  order by created_at limit 1) c
where f.fact_key = 'emergency-number-112'
on conflict do nothing;

-- starting-a-business
insert into public.expat_topics
  (slug, country, domain, pathway, content, fact_class, register, sort_order,
   published, needs_review, review_reason, last_verified_at, review_due_at)
values ('starting-a-business', 'GE', 'BUSINESS', 'INVEST', '{"en":{"title":"Starting a small business","summary":"Registering a business in Georgia is quick and done at one counter. Most freelancers and small traders start as an individual entrepreneur and apply for small business status.","sections":[{"kind":"SHORT_ANSWER","heading":"The short answer","body":"The two usual choices are an individual entrepreneur, which is you trading in your own name, and a limited liability company (LLC). Both are registered by the Public Registry, and you do it at a Public Service Hall. Registering an individual entrepreneur costs 26 lari for next working day, or 75 lari the same day. Registering a company costs 200 lari, or 400 lari the same day."},{"kind":"WHAT_YOU_NEED","heading":"What to bring","body":"For an individual entrepreneur, your passport and an address for the business. For a company you also need the charter signed by every founder, the consent of the person who will be director, and proof of the legal address, such as a lease or a letter from the owner. Papers signed abroad must be notarised and apostilled or legalised. A landlord letter has to be notarised in Georgia unless it is signed in front of the registry staff. If you do not speak Georgian, bring an interpreter, and ask the Public Service Hall for the current list before you go."},{"kind":"COST","heading":"Small business status, 1%","body":"An individual entrepreneur with yearly turnover under 500,000 lari can register as a small business and pay 1% of turnover instead of tax on profit. Above 500,000 lari the rate becomes 3%. A micro business, with turnover under 30,000 lari and no employees, pays no tax on that business income. These statuses are not automatic, you have to register for them. The Revenue Service (rs.ge) can tell you how. An LLC is taxed differently. Once taxable turnover passes 100,000 lari you must register for VAT."},{"kind":"PRACTICAL","heading":"A business bank account","body":"Once registered, open a business account at a Georgian bank. Each bank decides which papers it wants, so take your registration extract, your passport and a short, clear description of what the business does and where the money comes from. Our page on opening a bank account explains what to expect."},{"kind":"NOTES","heading":"Worth doing","body":"Talk to a local accountant before you register. They can tell you which form suits your work, whether small business status fits it, and what you must file each month. Your home country may also tax you, so check that side too."}]},"ka":{"title":"მცირე ბიზნესის დაწყება","summary":"საქართველოში ბიზნესის რეგისტრაცია სწრაფია და ერთ ფანჯარაში ხდება. ფრილანსერებისა და მცირე მოვაჭრეების უმეტესობა ინდივიდუალური მეწარმით იწყებს და მცირე ბიზნესის სტატუსს ითხოვს.","sections":[{"kind":"SHORT_ANSWER","heading":"მოკლე პასუხი","body":"ჩვეულებრივ ორ ფორმას ირჩევენ: ინდივიდუალური მეწარმე, ანუ საქმიანობა თქვენი სახელით, და შეზღუდული პასუხისმგებლობის საზოგადოება (შპს). ორივეს საჯარო რეესტრი არეგისტრირებს და ამას იუსტიციის სახლში აკეთებთ. ინდივიდუალური მეწარმის რეგისტრაცია 26 ლარი ღირს მომდევნო სამუშაო დღეს, ან 75 ლარი იმავე დღეს. კომპანიის რეგისტრაცია 200 ლარია, ან 400 ლარი იმავე დღეს."},{"kind":"WHAT_YOU_NEED","heading":"რა წაიღოთ","body":"ინდივიდუალური მეწარმისთვის პასპორტი და ბიზნესის მისამართი. კომპანიისთვის ასევე გჭირდებათ ყველა დამფუძნებლის ხელმოწერილი წესდება, დირექტორად დანიშნული პირის თანხმობა და იურიდიული მისამართის დამადასტურებელი დოკუმენტი, მაგალითად იჯარის ხელშეკრულება ან მესაკუთრის წერილი. საზღვარგარეთ ხელმოწერილი საბუთი ნოტარიულად დამოწმებული და აპოსტილირებული ან ლეგალიზებული უნდა იყოს. მესაკუთრის წერილი საქართველოში ნოტარიულად უნდა დამოწმდეს, თუ რეესტრის თანამშრომლის თანდასწრებით არ არის ხელმოწერილი. თუ ქართული არ იცით, წაიყვანეთ თარჯიმანი, და წასვლამდე იუსტიციის სახლში მოქმედი სია გადაამოწმეთ."},{"kind":"COST","heading":"მცირე ბიზნესის სტატუსი, 1%","body":"ინდივიდუალურ მეწარმეს, რომლის წლიური ბრუნვა 500 000 ლარზე ნაკლებია, შეუძლია მცირე ბიზნესის სტატუსი მიიღოს და მოგების გადასახადის ნაცვლად ბრუნვის 1% გადაიხადოს. 500 000 ლარს ზემოთ განაკვეთი 3% ხდება. მიკრო ბიზნესი, 30 000 ლარზე ნაკლები ბრუნვით და დაქირავებულების გარეშე, ამ შემოსავალზე გადასახადს არ იხდის. ეს სტატუსები ავტომატურად არ ენიჭება, მათთვის რეგისტრაცია გჭირდებათ. როგორ, ამას შემოსავლების სამსახური (rs.ge) გეტყვით. შპს სხვანაირად იბეგრება. როცა დასაბეგრი ბრუნვა 100 000 ლარს გადააჭარბებს, დღგ-ის გადამხდელად რეგისტრაცია სავალდებულოა."},{"kind":"PRACTICAL","heading":"ბიზნეს ანგარიში ბანკში","body":"რეგისტრაციის შემდეგ გახსენით ბიზნეს ანგარიში ქართულ ბანკში. რა საბუთს მოითხოვს, ყოველი ბანკი თავად წყვეტს, ამიტომ წაიღეთ რეგისტრაციის ამონაწერი, პასპორტი და მოკლე, გასაგები აღწერა, რას აკეთებს ბიზნესი და საიდან მოდის ფული. რას უნდა ელოდოთ, ჩვენს გვერდზე საბანკო ანგარიშის გახსნის შესახებ წაიკითხავთ."},{"kind":"NOTES","heading":"ღირს გააკეთოთ","body":"რეგისტრაციამდე გაესაუბრეთ ადგილობრივ ბუღალტერს. ის გეტყვით, რომელი ფორმა უხდება თქვენს საქმიანობას, შეესაბამება თუ არა მცირე ბიზნესის სტატუსი და რა უნდა წარადგინოთ ყოველთვე. შეიძლება თქვენმა ქვეყანამაც დაგაბეგროთ, ამიტომ ესეც გადაამოწმეთ."}]},"ru":{"title":"Как открыть небольшой бизнес","summary":"Регистрация бизнеса в Грузии быстрая и проходит в одном окне. Большинство фрилансеров и небольших торговцев начинают как индивидуальный предприниматель и оформляют статус малого бизнеса.","sections":[{"kind":"SHORT_ANSWER","heading":"Коротко","body":"Обычно выбирают одно из двух: индивидуальный предприниматель, то есть деятельность на ваше имя, или общество с ограниченной ответственностью (ООО). Оба регистрирует Публичный реестр, и делается это в Доме юстиции. Регистрация ИП стоит 26 лари на следующий рабочий день или 75 лари в тот же день. Регистрация компании стоит 200 лари или 400 лари в тот же день."},{"kind":"WHAT_YOU_NEED","heading":"Что взять с собой","body":"Для ИП паспорт и адрес для бизнеса. Для компании ещё нужен устав, подписанный всеми учредителями, согласие будущего директора и подтверждение юридического адреса, например договор аренды или письмо собственника. Документы, подписанные за границей, должны быть нотариально заверены и апостилированы или легализованы. Письмо собственника нужно заверить у нотариуса в Грузии, если его не подписывают при сотруднике реестра. Если не говорите по-грузински, возьмите переводчика и заранее уточните актуальный список в Доме юстиции."},{"kind":"COST","heading":"Статус малого бизнеса, 1%","body":"ИП с годовым оборотом меньше 500 000 лари может зарегистрироваться как малый бизнес и платить 1% от оборота вместо налога на прибыль. Свыше 500 000 лари ставка становится 3%. Микробизнес с оборотом меньше 30 000 лари и без сотрудников не платит налог с этого дохода. Эти статусы не присваиваются автоматически, для них нужно зарегистрироваться. Как именно, подскажет Служба доходов (rs.ge). ООО облагается иначе. Когда облагаемый оборот превышает 100 000 лари, нужно встать на учёт по НДС."},{"kind":"PRACTICAL","heading":"Бизнес счёт в банке","body":"После регистрации откройте бизнес счёт в грузинском банке. Какие документы нужны, каждый банк решает сам, поэтому возьмите выписку о регистрации, паспорт и короткое понятное описание, чем занимается бизнес и откуда деньги. Чего ожидать, мы рассказываем на странице об открытии банковского счёта."},{"kind":"NOTES","heading":"Стоит сделать","body":"До регистрации поговорите с местным бухгалтером. Он подскажет, какая форма подходит вашей работе, подходит ли статус малого бизнеса и что нужно сдавать каждый месяц. Ваша страна тоже может облагать вас налогом, так что проверьте и это."}]},"tr":{"title":"Küçük bir işletme kurmak","summary":"Gürcistan''da işletme kaydı hızlıdır ve tek bir gişede yapılır. Serbest çalışanların ve küçük esnafın çoğu bireysel girişimci olarak başlar ve küçük işletme statüsüne başvurur.","sections":[{"kind":"SHORT_ANSWER","heading":"Kısaca","body":"Genelde iki seçenek var: bireysel girişimci, yani kendi adınıza ticaret, ve limited şirket (LLC). İkisini de Kamu Sicili kaydeder, bunu bir Kamu Hizmetleri Salonu''nda yaparsınız. Bireysel girişimci kaydı ertesi iş günü için 26 lari, aynı gün için 75 lari. Şirket kaydı 200 lari, aynı gün için 400 lari."},{"kind":"WHAT_YOU_NEED","heading":"Yanınıza alın","body":"Bireysel girişimci için pasaportunuz ve işletme adresi. Şirket için ayrıca tüm kurucuların imzaladığı ana sözleşme, müdür olacak kişinin onayı ve kira sözleşmesi ya da malikten bir yazı gibi yasal adres belgesi gerekir. Yurt dışında imzalanan belgeler noter onaylı ve apostilli ya da tasdikli olmalıdır. Malik yazısı, sicil görevlisinin önünde imzalanmıyorsa Gürcistan''da notere onaylatılmalıdır. Gürcüce bilmiyorsanız bir tercüman götürün ve gitmeden önce güncel listeyi Kamu Hizmetleri Salonu''na sorun."},{"kind":"COST","heading":"Küçük işletme statüsü, %1","body":"Yıllık cirosu 500.000 larinin altında olan bireysel girişimci küçük işletme olarak kaydolabilir ve kâr vergisi yerine cironun %1''ini öder. 500.000 lariyi aşınca oran %3 olur. Cirosu 30.000 larinin altında ve çalışanı olmayan mikro işletme bu gelir üzerinden vergi ödemez. Bu statüler otomatik değildir, bunlar için kayıt olmanız gerekir. Nasıl yapılacağını Gelir İdaresi (rs.ge) söyler. Limited şirket farklı vergilendirilir. Vergiye tabi ciro 100.000 lariyi geçince KDV kaydı zorunludur."},{"kind":"PRACTICAL","heading":"İşletme banka hesabı","body":"Kayıttan sonra bir Gürcü bankasında işletme hesabı açın. Her banka hangi belgeleri istediğine kendi karar verir, bu yüzden kayıt özetinizi, pasaportunuzu ve işletmenin ne yaptığını ve paranın nereden geldiğini anlatan kısa, net bir açıklama götürün. Neler beklemeniz gerektiğini banka hesabı açma sayfamızda anlatıyoruz."},{"kind":"NOTES","heading":"Yapmaya değer","body":"Kaydolmadan önce yerel bir muhasebeciyle konuşun. Hangi biçimin işinize uyduğunu, küçük işletme statüsünün uygun olup olmadığını ve her ay neleri beyan etmeniz gerektiğini söyler. Kendi ülkeniz de sizi vergilendirebilir, onu da kontrol edin."}]},"ar":{"title":"تأسيس عمل صغير","summary":"تسجيل النشاط التجاري في جورجيا سريع ويتم عند شباك واحد. معظم العاملين المستقلين وأصحاب التجارة الصغيرة يبدؤون كرائد أعمال فردي ثم يطلبون صفة العمل الصغير.","sections":[{"kind":"SHORT_ANSWER","heading":"باختصار","body":"الخياران المعتادان هما رائد الأعمال الفردي، أي أن تعمل باسمك، والشركة ذات المسؤولية المحدودة. كلاهما يسجّله السجل العام، وتقوم بذلك في قاعة الخدمات العامة. تسجيل رائد الأعمال الفردي يكلّف 26 لاري في يوم العمل التالي، أو 75 لاري في اليوم نفسه. وتسجيل الشركة يكلّف 200 لاري، أو 400 لاري في اليوم نفسه."},{"kind":"WHAT_YOU_NEED","heading":"ما تحضره معك","body":"لرائد الأعمال الفردي: جوازك وعنوان للنشاط. وللشركة تحتاج أيضًا إلى النظام الأساسي موقّعًا من كل المؤسسين، وموافقة الشخص الذي سيكون مديرًا، وإثبات العنوان القانوني مثل عقد إيجار أو رسالة من المالك. الأوراق الموقّعة في الخارج يجب أن تكون موثّقة وعليها أبوستيل أو مصدّقة. ورسالة المالك يجب توثيقها عند كاتب عدل في جورجيا ما لم تُوقَّع أمام موظف السجل. وإذا كنت لا تتكلم الجورجية فخذ مترجمًا، واسأل قاعة الخدمات العامة عن القائمة الحالية قبل أن تذهب."},{"kind":"COST","heading":"صفة العمل الصغير، 1%","body":"رائد الأعمال الفردي الذي يقل دورانه السنوي عن 500,000 لاري يستطيع التسجيل كعمل صغير ودفع 1% من الدوران بدل ضريبة الأرباح. وفوق 500,000 لاري تصبح النسبة 3%. أما العمل المتناهي الصغر، بدوران أقل من 30,000 لاري ومن دون موظفين، فلا يدفع ضريبة على ذلك الدخل. هذه الصفات لا تُمنح تلقائيًا، بل يجب أن تسجّل لها، ومصلحة الإيرادات (rs.ge) تخبرك كيف. والشركة ذات المسؤولية المحدودة تخضع لضرائب مختلفة. وعندما يتجاوز الدوران الخاضع للضريبة 100,000 لاري يجب التسجيل في ضريبة القيمة المضافة."},{"kind":"PRACTICAL","heading":"حساب بنكي للعمل","body":"بعد التسجيل افتح حسابًا تجاريًا في بنك جورجي. كل بنك يقرر بنفسه الأوراق التي يريدها، فخذ مستخرج التسجيل وجوازك ووصفًا قصيرًا وواضحًا لما يفعله نشاطك ومن أين يأتي المال. وفي صفحتنا عن فتح حساب بنكي نشرح ما تتوقعه."},{"kind":"NOTES","heading":"يستحق أن تفعله","body":"تحدّث مع محاسب محلي قبل التسجيل. سيخبرك أي شكل يناسب عملك، وهل تناسبك صفة العمل الصغير، وما الذي يجب أن تقدّمه كل شهر. وقد يفرض بلدك أيضًا ضرائب عليك، فتحقق من ذلك أيضًا."}]},"he":{"title":"לפתוח עסק קטן","summary":"רישום עסק בגאורגיה מהיר ונעשה בדלפק אחד. רוב הפרילנסרים והסוחרים הקטנים מתחילים כיזם יחיד ומבקשים מעמד של עסק קטן.","sections":[{"kind":"SHORT_ANSWER","heading":"בקצרה","body":"שתי האפשרויות הרגילות הן יזם יחיד, כלומר עסק על שמכם, וחברה בערבון מוגבל. את שתיהן רושם המרשם הציבורי, ועושים את זה באולם שירותים ציבוריים. רישום יזם יחיד עולה 26 לארי ליום העבודה הבא, או 75 לארי באותו יום. רישום חברה עולה 200 לארי, או 400 לארי באותו יום."},{"kind":"WHAT_YOU_NEED","heading":"מה להביא","body":"ליזם יחיד: דרכון וכתובת לעסק. לחברה צריך גם תקנון חתום על ידי כל המייסדים, הסכמה של מי שיהיה המנהל, והוכחת כתובת רשומה, כמו חוזה שכירות או מכתב מבעל הנכס. מסמכים שנחתמו בחו״ל צריכים אישור נוטריוני ואפוסטיל או אישור קונסולרי. מכתב מבעל הנכס צריך אישור נוטריון בגאורגיה, אלא אם נחתם מול עובד המרשם. אם אתם לא מדברים גאורגית, הביאו מתורגמן, ושאלו באולם השירותים מה הרשימה העדכנית לפני שאתם הולכים."},{"kind":"COST","heading":"מעמד עסק קטן, 1%","body":"יזם יחיד עם מחזור שנתי מתחת ל־500,000 לארי יכול להירשם כעסק קטן ולשלם 1% מהמחזור במקום מס על הרווח. מעל 500,000 לארי השיעור עולה ל־3%. מיקרו עסק, עם מחזור מתחת ל־30,000 לארי ובלי עובדים, לא משלם מס על ההכנסה הזו. המעמדות האלה לא אוטומטיים, צריך להירשם אליהם. רשות המסים (rs.ge) תסביר לכם איך. חברה בערבון מוגבל ממוסה אחרת. כשהמחזור החייב עובר 100,000 לארי, חובה להירשם למע״מ."},{"kind":"PRACTICAL","heading":"חשבון בנק לעסק","body":"אחרי הרישום פתחו חשבון עסקי בבנק גאורגי. כל בנק מחליט בעצמו אילו מסמכים הוא רוצה, אז הביאו את נסח הרישום, דרכון ותיאור קצר וברור של מה העסק עושה ומאיפה מגיע הכסף. בעמוד שלנו על פתיחת חשבון בנק אנחנו מסבירים למה לצפות."},{"kind":"NOTES","heading":"כדאי לעשות","body":"דברו עם רואה חשבון מקומי לפני הרישום. הוא יגיד לכם איזו צורה מתאימה לעבודה שלכם, האם מעמד עסק קטן מתאים, ומה צריך להגיש כל חודש. גם המדינה שלכם עשויה למסות אתכם, אז בדקו גם את הצד הזה."}]}}'::jsonb,
        'FEE', 'OFFICIAL_REQUIREMENT', 100,
        true, false, null,
        now(), now() + interval '90 days')
on conflict (slug) do update set
  domain = excluded.domain,
  pathway = excluded.pathway,
  content = excluded.content,
  fact_class = excluded.fact_class,
  register = excluded.register,
  sort_order = excluded.sort_order,
  published = excluded.published,
  needs_review = excluded.needs_review,
  review_reason = excluded.review_reason,
  last_verified_at = excluded.last_verified_at,
  review_due_at = excluded.review_due_at,
  updated_at = now();
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'registration-fees', 'FEE', 'OFFICIAL_REQUIREMENT', 'ESTABLISHED',
       '{"en":"Businesses are registered by the National Agency of Public Registry through the Public Service Hall. Registering an individual entrepreneur costs 26 GEL in one working day or 75 GEL on the day of application. Registering any other entrepreneur, such as an LLC, costs 200 GEL in one working day or 400 GEL on the day.","ka":"ბიზნესს საჯარო რეესტრის ეროვნული სააგენტო არეგისტრირებს იუსტიციის სახლის მეშვეობით. ინდივიდუალური მეწარმის რეგისტრაცია ღირს 26 ლარი ერთ სამუშაო დღეში ან 75 ლარი განცხადების დღეს. სხვა მეწარმის, მაგალითად შპს-ის, რეგისტრაცია ღირს 200 ლარი ერთ სამუშაო დღეში ან 400 ლარი იმავე დღეს.","ru":"Бизнес регистрирует Национальное агентство публичного реестра через Дом юстиции. Регистрация ИП стоит 26 лари за один рабочий день или 75 лари в день подачи. Регистрация другого предпринимателя, например ООО, стоит 200 лари за один рабочий день или 400 лари в тот же день.","tr":"İşletmeleri Kamu Sicili Ulusal Ajansı, Kamu Hizmetleri Salonu aracılığıyla kaydeder. Bireysel girişimci kaydı bir iş gününde 26 GEL, başvuru günü 75 GEL''dir. Limited şirket gibi diğer girişimcilerin kaydı bir iş gününde 200 GEL, aynı gün 400 GEL''dir.","ar":"تسجّل الوكالة الوطنية للسجل العام الأنشطة التجارية عبر قاعة الخدمات العامة. تسجيل رائد الأعمال الفردي يكلّف 26 لاري خلال يوم عمل واحد أو 75 لاري في يوم تقديم الطلب. وتسجيل أي كيان آخر، مثل الشركة ذات المسؤولية المحدودة، يكلّف 200 لاري خلال يوم عمل أو 400 لاري في اليوم نفسه.","he":"את העסקים רושמת הסוכנות הלאומית לרישום ציבורי דרך אולם השירותים הציבוריים. רישום יזם יחיד עולה 26 לארי תוך יום עבודה אחד או 75 לארי ביום הגשת הבקשה. רישום כל יזם אחר, כמו חברה בערבון מוגבל, עולה 200 לארי תוך יום עבודה או 400 לארי באותו יום."}'::jsonb, '{"currency":"GEL","individualEntrepreneur":26,"individualEntrepreneurSameDay":75,"company":200,"companySameDay":400}'::jsonb, null,
       false
from public.expat_topics where slug = 'starting-a-business'
on conflict (topic_id, fact_key) do update set
  fact_class = excluded.fact_class,
  register = excluded.register,
  availability = excluded.availability,
  statement = excluded.statement,
  value = excluded.value,
  applies_to_nationalities = excluded.applies_to_nationalities,
  needs_review = excluded.needs_review,
  updated_at = now();
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'starting-a-business'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'National Agency of Public Registry' and url is not distinct from 'https://napr.gov.ge/en/page/fees-and-terms'
  order by created_at limit 1) c
where f.fact_key = 'registration-fees'
on conflict do nothing;
insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'starting-a-business'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'Invest in Georgia' and url is not distinct from 'https://www.investingeorgia.org/resources/how-to-register-a-business/'
  order by created_at limit 1) c
where f.fact_key = 'registration-fees'
on conflict do nothing;
insert into public.expat_topic_facts
  (topic_id, fact_key, fact_class, register, availability, statement, value,
   applies_to_nationalities, needs_review)
select id, 'small-business-status', 'LEGAL', 'PRACTICAL_CONTEXT', 'ESTABLISHED',
       '{"en":"An individual entrepreneur with turnover under 500,000 GEL may register as a small business and pay 1% of turnover, rising to 3% above that. A micro business with turnover under 30,000 GEL and no employees is exempt on its business income. VAT registration is required once taxable turnover exceeds 100,000 GEL.","ka":"ინდივიდუალურ მეწარმეს 500 000 ლარზე ნაკლები ბრუნვით შეუძლია მცირე ბიზნესად დარეგისტრირდეს და ბრუნვის 1% გადაიხადოს, ამ ზღვრის ზემოთ კი 3%. მიკრო ბიზნესი 30 000 ლარზე ნაკლები ბრუნვით და დაქირავებულების გარეშე სამეწარმეო შემოსავალზე გადასახადისგან თავისუფალია. დღგ-ის რეგისტრაცია სავალდებულოა, როცა დასაბეგრი ბრუნვა 100 000 ლარს აჭარბებს.","ru":"ИП с оборотом меньше 500 000 лари может зарегистрироваться как малый бизнес и платить 1% от оборота, а выше этого порога 3%. Микробизнес с оборотом меньше 30 000 лари и без сотрудников освобождён от налога на доход от бизнеса. Регистрация по НДС обязательна, когда облагаемый оборот превышает 100 000 лари.","tr":"Cirosu 500.000 GEL''in altındaki bireysel girişimci küçük işletme olarak kaydolup cironun %1''ini ödeyebilir, bu sınırın üstünde oran %3 olur. Cirosu 30.000 GEL''in altında ve çalışanı olmayan mikro işletme ticari gelirinde vergiden muaftır. Vergiye tabi ciro 100.000 GEL''i aşınca KDV kaydı zorunludur.","ar":"يمكن لرائد الأعمال الفردي الذي يقل دورانه عن 500,000 لاري أن يسجّل كعمل صغير ويدفع 1% من الدوران، وترتفع النسبة إلى 3% فوق ذلك. والعمل المتناهي الصغر بدوران أقل من 30,000 لاري ومن دون موظفين معفى من الضريبة على دخله التجاري. ويجب التسجيل في ضريبة القيمة المضافة متى تجاوز الدوران الخاضع للضريبة 100,000 لاري.","he":"יזם יחיד עם מחזור מתחת ל־500,000 לארי יכול להירשם כעסק קטן ולשלם 1% מהמחזור, ומעל לסף הזה 3%. מיקרו עסק עם מחזור מתחת ל־30,000 לארי ובלי עובדים פטור ממס על ההכנסה העסקית. רישום למע״מ חובה כשהמחזור החייב במס עובר 100,000 לארי."}'::jsonb, '{"rate":0.01,"rateAbove":0.03,"turnoverLimitGel":500000,"microLimitGel":30000,"vatThresholdGel":100000}'::jsonb, null,
       false
from public.expat_topics where slug = 'starting-a-business'
on conflict (topic_id, fact_key) do update set
