insert into public.expat_fact_citations (fact_id, citation_id)
select f.id, c.id
from public.expat_topic_facts f
join public.expat_topics t on t.id = f.topic_id and t.slug = 'starting-a-business'
cross join lateral (
  select id from public.expat_citations
  where publisher = 'PwC Worldwide Tax Summaries' and url is not distinct from 'https://taxsummaries.pwc.com/georgia/corporate/other-taxes'
  order by created_at limit 1) c
where f.fact_key = 'small-business-status'
on conflict do nothing;

-- Observed prices. Supersede rather than overwrite, so a change is visible.

